implementations.python:
def pair_count(n):
    # Contract: 0 <= n <= 1_000_000; count pairs 0 <= j < i < n.
    if not isinstance(n, int) or not 0 <= n <= 1_000_000:
        raise ValueError("n outside contract")
    return n * (n - 1) // 2

def measured_pairs(n):
    count = 0
    for i in range(n):
        for j in range(i):
            count += 1
    return count

assert pair_count(6) == measured_pairs(6) == 15

implementations.cpp:
#include <cassert>
#include <stdexcept>
using namespace std;
long long pair_count(long long n) {
    if (n < 0 || n > 1000000) throw invalid_argument("n outside contract");
    return n * (n - 1) / 2; // multiplication occurs in 64 bits
}
long long measured_pairs(int n) {
    long long count = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < i; ++j) ++count;
    return count;
}
int main() { assert(pair_count(6) == 15); assert(measured_pairs(6) == 15); }

implementations.java:
class PairCount {
    static long pairCount(long n) {
        if (n < 0 || n > 1000000) throw new IllegalArgumentException("n outside contract");
        return n * (n - 1) / 2;
    }
    static long measuredPairs(int n) {
        long count = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < i; j++) count++;
        return count;
    }
    public static void main(String[] args) {
        if (pairCount(6) != 15 || measuredPairs(6) != 15) throw new AssertionError();
    }
}

