function pairCount(n: number): number {
  if (!Number.isInteger(n) || n < 0 || n > 1000000) throw new RangeError("n outside contract");
  return n * (n - 1) / 2;
}
function measuredPairs(n: number): number {
  let count = 0;
  for (let i = 0; i < n; i++)
    for (let j = 0; j < i; j++) count++;
  return count;
}
console.log(pairCount(6), measuredPairs(6)); // 15 15

